import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';
import toast from 'react-hot-toast';

const ProblemList = () => {
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(true);
  const { token, user } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    fetchProblems();
  }, []);

  const fetchProblems = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/problems', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProblems(response.data.problems || []);
    } catch (error) {
      console.error('Error fetching problems:', error);
      toast.error('Failed to load problems');
    } finally {
      setLoading(false);
    }
  };

  const getDifficultyColor = (difficulty) => {
    switch (difficulty) {
      case 'Easy': return { bg: '#d4edda', color: '#155724', gradient: 'linear-gradient(135deg, #d4edda, #b7e4c7)' };
      case 'Medium': return { bg: '#fff3cd', color: '#856404', gradient: 'linear-gradient(135deg, #fff3cd, #ffe69b)' };
      case 'Hard': return { bg: '#f8d7da', color: '#721c24', gradient: 'linear-gradient(135deg, #f8d7da, #f5c6cb)' };
      default: return { bg: '#e2e3e5', color: '#383d41', gradient: 'linear-gradient(135deg, #e2e3e5, #d6d8db)' };
    }
  };

  const handleProblemClick = (problemId) => {
    navigate(`/problems/${problemId}`);
  };

  const handleDelete = async (e, problemId) => {
    e.stopPropagation();
    if (!window.confirm('Are you sure you want to delete this problem?')) return;
    try {
      await axios.delete(`http://localhost:5000/api/admin/problems/${problemId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      toast.success('Problem deleted!');
      fetchProblems();
    } catch (error) {
      toast.error('Failed to delete problem');
    }
  };

  const canDelete = user?.role === 'admin' || user?.role === 'setter';

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div className="spinner"></div>
        <p>Loading problems...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1 style={styles.title}>📚 Problems</h1>
        <p style={styles.subtitle}>Solve coding problems and improve your skills</p>
      </div>

      <div style={styles.list}>
        {problems.length === 0 ? (
          <div style={styles.emptyState}>
            <span style={styles.emptyIcon}>📭</span>
            <p>No problems available</p>
          </div>
        ) : (
          problems.map((problem, index) => {
            const diff = getDifficultyColor(problem.difficulty);
            return (
              <div
                key={problem._id}
                style={styles.problemRow}
                onClick={() => handleProblemClick(problem._id)}
              >
                <div style={styles.cardGradient}></div>
                <div style={styles.cardContent}>
                  <div style={styles.leftSection}>
                    <div style={styles.problemNumber}>#{index + 1}</div>
                    <div style={styles.problemInfo}>
                      <div style={styles.problemTitle}>{problem.title}</div>
                      <div style={styles.problemMeta}>
                        <span style={{
                          ...styles.difficultyBadge,
                          background: diff.bg,
                          color: diff.color,
                        }}>
                          {problem.difficulty || 'Easy'}
                        </span>
                        <span style={styles.problemId}>ID: {problem._id}</span>
                      </div>
                    </div>
                  </div>
                  <div style={styles.rightSection}>
                    {canDelete && (
                      <button
                        style={styles.deleteBtn}
                        onClick={(e) => handleDelete(e, problem._id)}
                        title="Delete Problem"
                      >
                        🗑️
                      </button>
                    )}
                    <button style={styles.solveButton}>
                      Solve →
                    </button>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

const styles = {
  container: {
    padding: '30px',
    maxWidth: '1000px',
    margin: '0 auto',
    minHeight: '100vh',
    background: '#f0f2f5',
  },
  header: {
    marginBottom: '30px',
  },
  title: {
    fontSize: '28px',
    fontWeight: 700,
    color: '#1a1a2e',
    marginBottom: '8px',
  },
  subtitle: {
    fontSize: '16px',
    color: '#888',
  },
  list: {
    display: 'flex',
    flexDirection: 'column',
    gap: '16px',
  },
  problemRow: {
    position: 'relative',
    borderRadius: '14px',
    overflow: 'hidden',
    cursor: 'pointer',
    boxShadow: '0 4px 15px rgba(0,0,0,0.06)',
    transition: 'all 0.3s ease',
    border: '1px solid transparent',
  },
  cardGradient: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    background: 'linear-gradient(135deg, #ffffff, #f8f9fa)',
    zIndex: 0,
  },
  cardContent: {
    position: 'relative',
    zIndex: 1,
    padding: '20px 24px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    background: 'rgba(255,255,255,0.8)',
    backdropFilter: 'blur(10px)',
    border: '1px solid rgba(255,255,255,0.3)',
  },
  leftSection: {
    display: 'flex',
    alignItems: 'center',
    gap: '20px',
    flex: 1,
  },
  problemNumber: {
    fontSize: '14px',
    fontWeight: 700,
    color: '#6C63FF',
    minWidth: '50px',
    background: 'rgba(108, 99, 255, 0.1)',
    padding: '4px 12px',
    borderRadius: '20px',
    textAlign: 'center',
  },
  problemInfo: {
    display: 'flex',
    flexDirection: 'column',
    gap: '4px',
  },
  problemTitle: {
    fontSize: '17px',
    fontWeight: 600,
    color: '#1a1a2e',
  },
  problemMeta: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    flexWrap: 'wrap',
  },
  difficultyBadge: {
    padding: '2px 14px',
    borderRadius: '20px',
    fontSize: '11px',
    fontWeight: 600,
  },
  problemId: {
    fontSize: '12px',
    color: '#999',
  },
  rightSection: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
  },
  deleteBtn: {
    background: 'rgba(244, 67, 54, 0.1)',
    color: '#ef5350',
    border: '1px solid rgba(244, 67, 54, 0.2)',
    padding: '8px 12px',
    borderRadius: '8px',
    cursor: 'pointer',
    fontSize: '16px',
    transition: 'all 0.3s ease',
  },
  solveButton: {
    padding: '10px 28px',
    background: 'linear-gradient(135deg, #FF8C00, #FF6600)',
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    fontSize: '14px',
    fontWeight: 600,
    cursor: 'pointer',
    transition: 'all 0.3s ease',
    boxShadow: '0 4px 15px rgba(255, 140, 0, 0.3)',
    letterSpacing: '0.3px',
  },
  loadingContainer: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '60vh',
  },
  emptyState: {
    textAlign: 'center',
    padding: '60px 20px',
    color: '#999',
    background: 'white',
    borderRadius: '14px',
  },
  emptyIcon: {
    fontSize: '48px',
    display: 'block',
    marginBottom: '12px',
  },
};

// Hover effect - add to card
const style = document.createElement('style');
style.textContent = `
  .problem-row:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 30px rgba(108, 99, 255, 0.15);
    border-color: #6C63FF;
  }
  .problem-row:hover .solve-button {
    transform: scale(1.05);
    box-shadow: 0 6px 25px rgba(255, 140, 0, 0.4);
  }
  .problem-row:hover .card-content {
    background: rgba(255,255,255,0.95);
  }
`;
document.head.appendChild(style);

export default ProblemList;
